<script setup lang="ts">
import { computed, ref } from 'vue'
import { useWorkspaceStore } from '../stores/workspace'
import { methodName, percent } from '../components/format'
const store = useWorkspaceStore(), runId = ref('')
const rows = computed(() => { const rows = [...store.comparisons]; if (store.activeRun?.status === 'succeeded' && store.evaluation && !rows.some(x => x.run.run_id === store.activeRun?.run_id)) rows.unshift({ run: store.activeRun, evaluation: store.evaluation }); return rows })
</script>
<template>
  <div class="section-heading"><div><span class="eyebrow">EXPERIMENT REVIEW</span><h2>同时查看误报、漏报与覆盖范围</h2><p>所有指标由保存的完整分钟评价提供，页面只做展示。</p></div></div>
  <article class="panel"><div class="panel-heading"><h3>加入已完成任务</h3><span class="tag">按 run_id 查询</span></div><form class="inline-form" @submit.prevent="store.compare(runId)"><label class="grow">任务编号<input v-model="runId" required placeholder="输入要并列查看的 run_id" pattern="[a-zA-Z0-9][a-zA-Z0-9_\-]{0,95}"></label><button class="secondary">添加任务</button></form><p class="hint">当前只并列展示原始评价，不自动认定同条件或计算优劣。正式比较仍需 W1 确认共同有效分钟、数据版本与配置。</p></article>
  <div class="metric-strip" v-if="store.evaluation?.available && store.evaluation.metrics"><article><small>精确率</small><strong>{{ percent(store.evaluation.metrics.precision) }}</strong><span>Precision</span></article><article><small>攻击召回率</small><strong>{{ percent(store.evaluation.metrics.recall) }}</strong><span>Recall</span></article><article><small>F1</small><strong>{{ percent(store.evaluation.metrics.f1) }}</strong><span>原始逐分钟预测</span></article><article><small>正常误报率</small><strong class="coral-text">{{ percent(store.evaluation.metrics.fpr) }}</strong><span>False positive rate</span></article></div>
  <article class="panel"><div class="panel-heading"><h3>任务评价对照</h3><span class="hint">合成数值不用于研究结论</span></div><div v-if="!rows.length" class="empty">尚无可比较任务，请先打开完成结果。</div><div v-else class="table-scroll"><table><thead><tr><th>任务 / 方法</th><th>数据 / 划分 / 窗口</th><th>精确率</th><th>召回率</th><th>F1</th><th>误报率</th><th>TP / FP / TN / FN</th><th>身份</th></tr></thead><tbody><tr v-for="row in rows" :key="row.run.run_id"><td><strong>{{ methodName[row.run.config.method] }}</strong><small class="mono">{{ row.run.run_id }}</small></td><td>{{ row.run.config.dataset_id }}<small>{{ row.run.config.split_id }} · H={{ row.run.config.window_minutes }}</small></td><td>{{ percent(row.evaluation.metrics?.precision) }}</td><td>{{ percent(row.evaluation.metrics?.recall) }}</td><td>{{ percent(row.evaluation.metrics?.f1) }}</td><td>{{ percent(row.evaluation.metrics?.fpr) }}</td><td>{{ row.evaluation.metrics ? `${row.evaluation.metrics.tp} / ${row.evaluation.metrics.fp} / ${row.evaluation.metrics.tn} / ${row.evaluation.metrics.fn}` : '不可评价' }}</td><td>{{ row.evaluation.evidence_kind }}</td></tr></tbody></table></div></article>
  <div class="analysis-grid" v-for="row in rows" :key="row.run.run_id"><article class="panel"><h3>覆盖与排除 · {{ row.run.run_id }}</h3><p v-if="!row.evaluation.available" class="failure-message">不可评价：{{ row.evaluation.reason }}</p><dl class="facts"><div><dt>正常分钟 · 可用 / 全部</dt><dd>{{ row.evaluation.normal_coverage.eligible }} / {{ row.evaluation.normal_coverage.total }}</dd></div><div><dt>攻击分钟 · 可用 / 全部</dt><dd>{{ row.evaluation.attack_coverage.eligible }} / {{ row.evaluation.attack_coverage.total }}</dd></div><div><dt>被排除攻击分钟</dt><dd>{{ row.evaluation.excluded_attack_minutes }}</dd></div><div><dt>仅背景标签分钟</dt><dd>{{ row.evaluation.background_only_minutes }}</dd></div></dl><p v-if="row.evaluation.metrics?.undefined_reasons.length" class="hint">无分母指标：{{ row.evaluation.metrics.undefined_reasons.join('、') }}，显示不可评价。</p></article><article class="panel"><h3>高负载分组</h3><template v-if="row.evaluation.high_load_metrics"><dl class="facts"><div><dt>误报率</dt><dd>{{ percent(row.evaluation.high_load_metrics.fpr) }}</dd></div><div><dt>攻击召回率</dt><dd>{{ percent(row.evaluation.high_load_metrics.recall) }}</dd></div></dl></template><div v-else class="empty compact"><strong>暂不可评价</strong><p>{{ row.evaluation.high_load_unavailable_reason }}</p></div><p class="hint">计数口径未核实前不展示高负载结论。</p></article></div>
  <article class="panel" v-if="store.activeRun?.status === 'succeeded'"><div class="panel-heading"><div><h3>导出任务记录</h3><p class="hint">导出完整结果，不受页面范围、分页或图表抽样影响。</p></div></div><div class="button-row"><button class="secondary" @click="store.download('metrics')">评价 JSON ↓</button><button class="secondary" @click="store.download('config')">配置 JSON ↓</button><button class="secondary" @click="store.download('scores')">完整分数 Parquet ↓</button></div><p v-if="store.mode === 'mock'" class="hint">合成模式只提供评价与配置 JSON，Parquet 导出等待 W1/W2 产物。</p></article>
</template>
